<?php
declare(strict_types=1);
namespace Modules\Integrations;

/** Content-addressed immutable originals and separately HMAC-authenticated send spool. */
final class PrivateStore
{
    public function __construct(private string $root,private string $key) {if(strlen($key)<32)throw new \RuntimeException('PRIVATE_KEY_REQUIRED'); if(!is_dir($root)&&!mkdir($root,0700,true))throw new \RuntimeException('PRIVATE_STORE_FAILED'); if(is_link($root))throw new \RuntimeException('PRIVATE_STORE_LINK'); $this->root=(string)realpath($root);}
    public function put(string $kind,string $bytes): string {if(!preg_match('/^[a-z-]+$/D',$kind))throw new \InvalidArgumentException('INVALID_STORE_KIND'); $sha=hash('sha256',$bytes); $dir=$this->root.'/'.$kind; if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new \RuntimeException('PRIVATE_STORE_FAILED'); $rel=$kind.'/'.$sha; $path=$this->root.'/'.$rel; if(is_link($path))throw new \RuntimeException('PRIVATE_STORE_LINK'); if(is_file($path)){if(!hash_equals($sha,(string)hash_file('sha256',$path)))throw new \RuntimeException('IMMUTABLE_CORRUPTION'); return $rel;} $f=@fopen($path,'xb'); if(!$f){if(is_file($path)&&hash_equals($sha,(string)hash_file('sha256',$path)))return $rel;throw new \RuntimeException('PRIVATE_WRITE_FAILED');} try{if(fwrite($f,$bytes)!==strlen($bytes))throw new \RuntimeException('PRIVATE_WRITE_FAILED');fflush($f);if(function_exists('fsync'))fsync($f);}finally{fclose($f);} chmod($path,0600);return $rel;}
    public function read(string $rel,?string $sha=null): string {if(!preg_match('/^[a-z-]+\/[a-f0-9]{64}$/D',$rel))throw new \RuntimeException('INVALID_PRIVATE_PATH');$p=$this->root.'/'.$rel;if(!is_file($p)||is_link($p))throw new \RuntimeException('PRIVATE_FILE_MISSING');$b=file_get_contents($p);if(!is_string($b)||!hash_equals($sha??basename($rel),hash('sha256',$b)))throw new \RuntimeException('PRIVATE_FILE_CORRUPT');return $b;}
    /** Internal streaming export path; never derived from a source filename or returned to a browser. */
    public function verifiedPath(string $relative,?string $sha=null): string {
        if(!preg_match('/^[a-z-]+\/[a-f0-9]{64}$/D',$relative))throw new \RuntimeException('INVALID_PRIVATE_PATH');
        [$kind]=explode('/',$relative);
        $path=$this->root.'/'.$relative;
        if(is_link($this->root.'/'.$kind)||is_link($path)||!is_file($path))throw new \RuntimeException('PRIVATE_FILE_MISSING');
        if(!hash_equals($sha??basename($relative),(string)hash_file('sha256',$path)))throw new \RuntimeException('PRIVATE_FILE_CORRUPT');
        return $path;
    }
    public function spool(array $context,string $raw): string {$record=['version'=>1,'context'=>$context,'raw_base64'=>base64_encode($raw),'sha256'=>hash('sha256',$raw)];$payload=Support::json($record);return $this->put('spool',Support::json(['payload'=>$record,'hmac'=>hash_hmac('sha256',$payload,$this->key)]));}
    public function verifySpool(string $path): array {$v=json_decode($this->read($path),true,64,JSON_THROW_ON_ERROR);if(!is_array($v['payload']??null)||!is_string($v['hmac']??null)||!hash_equals(hash_hmac('sha256',Support::json($v['payload']),$this->key),$v['hmac']))throw new \RuntimeException('SPOOL_HMAC_FAILED');$raw=base64_decode($v['payload']['raw_base64']??'',true);if($raw===false||!hash_equals($v['payload']['sha256']??'',hash('sha256',$raw)))throw new \RuntimeException('SPOOL_BYTES_FAILED');return $v['payload'];}
    public function linkReceipt(string $attemptId,string $receiptPath): void {if(!preg_match('/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/D',$attemptId))throw new \InvalidArgumentException('INVALID_ATTEMPT_ID');$receipt=$this->verifySpool($receiptPath);if(($receipt['context']['attempt_id']??null)!==$attemptId||($receipt['context']['kind']??null)!=='transport_receipt')throw new \RuntimeException('RECEIPT_ATTEMPT_BINDING_FAILED');$dir=$this->root.'/receipt-links';if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new \RuntimeException('RECEIPT_INDEX_FAILED');$payload=['attempt_id'=>$attemptId,'receipt_path'=>$receiptPath];$bytes=Support::json(['payload'=>$payload,'hmac'=>hash_hmac('sha256',Support::json($payload),$this->key)]);$path=$dir.'/'.hash('sha256',$attemptId);if(is_link($path))throw new \RuntimeException('RECEIPT_INDEX_LINK');$f=@fopen($path,'xb');if(!$f){if(is_file($path)&&hash_equals(hash('sha256',$bytes),(string)hash_file('sha256',$path)))return;throw new \RuntimeException('RECEIPT_INDEX_CONFLICT');}try{if(fwrite($f,$bytes)!==strlen($bytes))throw new \RuntimeException('RECEIPT_INDEX_FAILED');fflush($f);if(function_exists('fsync'))fsync($f);}finally{fclose($f);}chmod($path,0600);}
    public function receiptFor(string $attemptId): ?array {if(!preg_match('/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/D',$attemptId))throw new \InvalidArgumentException('INVALID_ATTEMPT_ID');$path=$this->root.'/receipt-links/'.hash('sha256',$attemptId);if(!is_file($path))return null;if(is_link($path)||filesize($path)>4096)throw new \RuntimeException('RECEIPT_INDEX_INVALID');$v=json_decode(file_get_contents($path),true,16,JSON_THROW_ON_ERROR);$p=$v['payload']??null;if(!is_array($p)||($p['attempt_id']??'')!==$attemptId||!hash_equals(hash_hmac('sha256',Support::json($p),$this->key),$v['hmac']??''))throw new \RuntimeException('RECEIPT_INDEX_HMAC_FAILED');$receipt=$this->verifySpool($p['receipt_path']);if(($receipt['context']['attempt_id']??null)!==$attemptId)throw new \RuntimeException('RECEIPT_ATTEMPT_BINDING_FAILED');return ['receipt_path'=>$p['receipt_path'],'receipt'=>$receipt];}
}
